abstract class PaymentRequestBuilder<B extends PaymentRequestBuilder<B>> {
    protected long cents;
    protected String currency;

    B amount(long cents) { this.cents = cents; return self(); }
    B currency(String code) { this.currency = code; return self(); }
    protected abstract B self();
}

final class CardPaymentBuilder extends PaymentRequestBuilder<CardPaymentBuilder> {
    private String token;

    CardPaymentBuilder cardToken(String token) { this.token = token; return this; }
    @Override protected CardPaymentBuilder self() { return this; }

    CardPayment build() {
        if (cents <= 0) throw new IllegalStateException("amount must be positive");
        return new CardPayment(cents, currency, "", token);
    }
}

// new CardPaymentBuilder().amount(1_200).currency("EUR").cardToken("tok_42").build();

